create table if not exists public.event_records (
  id bigint generated by default as identity primary key,
  dataset_id integer not null
    references public.datasets(id) on delete cascade,
  row_number smallint not null check (row_number between 1 and 500),
  source_file text not null,
  data jsonb not null check (jsonb_typeof(data) = 'object'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (dataset_id, row_number)
);

drop trigger if exists event_records_set_updated_at
  on public.event_records;
create trigger event_records_set_updated_at
before update on public.event_records
for each row execute function private.set_updated_at();

alter table public.event_records enable row level security;

revoke all on table public.event_records from anon, authenticated;
revoke all on sequence public.event_records_id_seq from anon, authenticated;
grant select, update on table public.event_records to service_role;

insert into public.datasets
  (name, kind, description, status, member_ids, reuse_count, validation_state)
select
  'Kid Events · Ages 35–50',
  'event',
  'Complete bilingual game event rotation for the age 35–50 journey.',
  'ready',
  '{}'::integer[],
  0,
  'valid'
where not exists (
  select 1
  from public.datasets
  where lower(name) = lower('Kid Events · Ages 35–50')
);

