insert into public.event_records
  (dataset_id, row_number, source_file, data)
select
  target_dataset.id,
  source_rows.row_number,
  'AGAP008 - CFG_Latest-Kid Event List 25-40 (1May).csv',
  source_rows.event_data
from target_dataset
cross join source_rows
on conflict (dataset_id, row_number) do update
set
  source_file = excluded.source_file,
  data = excluded.data;

update public.datasets as dataset
set member_ids = (
  select array_agg(record.id::integer order by record.row_number)
  from public.event_records as record
  where record.dataset_id = dataset.id
)
where lower(dataset.name) in (
  lower('Kid Events · Ages 35–50'),
  lower('Kid Events · Ages 25–40')
);
